<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4️⃣-load-graph" tabindex="-1"><a class="header-anchor" href="#_4️⃣-load-graph"><span>4️⃣ LOAD GRAPH</span></a></h3>
<div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre v-pre><code><span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token comment">// 📖 4️⃣ LOAD GRAPH (تحميل البيانات)</span></span>
<span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">loadGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 📥 نقرأ البيانات من LocalStorage</span></span>
<span class="line">  <span class="token keyword">const</span> graph <span class="token operator">=</span> <span class="token function">getGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token comment">// 🧠 لو فيه بيانات محفوظة</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>graph<span class="token punctuation">.</span>nodes<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    nodes<span class="token punctuation">.</span>value <span class="token operator">=</span> graph<span class="token punctuation">.</span>nodes<span class="token punctuation">;</span></span>
<span class="line">    edges<span class="token punctuation">.</span>value <span class="token operator">=</span> graph<span class="token punctuation">.</span>edges<span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 🆕 لو مفيش بيانات → ننشئ جراف افتراضي</span></span>
<span class="line">    <span class="token function">createDefaultGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5️⃣-create-default-graph" tabindex="-1"><a class="header-anchor" href="#_5️⃣-create-default-graph"><span>5️⃣ Create Default Graph</span></a></h3>
<div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre v-pre><code><span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token comment">// 🆕 5️⃣ Create Default Graph (أول تشغيل)</span></span>
<span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">createDefaultGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 🆔 إنشاء ID فريد</span></span>
<span class="line">  <span class="token keyword">const</span> startId <span class="token operator">=</span> <span class="token function">nanoid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> endId <span class="token operator">=</span> <span class="token function">nanoid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token comment">// 📦 إنشاء Nodes</span></span>
<span class="line">  nodes<span class="token punctuation">.</span>value <span class="token operator">=</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">id</span><span class="token operator">:</span> startId<span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">position</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">80</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">label</span><span class="token operator">:</span> <span class="token string">"Start 🚀"</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">id</span><span class="token operator">:</span> endId<span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">position</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">300</span><span class="token punctuation">,</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">label</span><span class="token operator">:</span> <span class="token string">"End 🏁"</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token comment">// 🔗 ربط Start → End</span></span>
<span class="line">  edges<span class="token punctuation">.</span>value <span class="token operator">=</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">id</span><span class="token operator">:</span> <span class="token function">nanoid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">source</span><span class="token operator">:</span> startId<span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">target</span><span class="token operator">:</span> endId<span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6️⃣-auto-save" tabindex="-1"><a class="header-anchor" href="#_6️⃣-auto-save"><span>6️⃣ Auto Save</span></a></h3>
<div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre v-pre><code><span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token comment">// 💾 6️⃣ Auto Save (حفظ تلقائي)</span></span>
<span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token comment">// ⏳ Debounce: يمنع الحفظ كل جزء من الثانية</span></span>
<span class="line"><span class="token comment">// بدل ما يحفظ كل حركة Drag</span></span>
<span class="line"><span class="token keyword">const</span> debouncedSave <span class="token operator">=</span> <span class="token function">debounce</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 💾 احفظ الجراف بالكامل</span></span>
<span class="line">  <span class="token function">saveGraph</span><span class="token punctuation">(</span>nodes<span class="token punctuation">.</span>value<span class="token punctuation">,</span> edges<span class="token punctuation">.</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">500</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// بعد 500ms من آخر تغيير</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 👀 مراقبة أي تغيير في nodes أو edges</span></span>
<span class="line"><span class="token function">watch</span><span class="token punctuation">(</span></span>
<span class="line">  <span class="token punctuation">[</span>nodes<span class="token punctuation">,</span> edges<span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token comment">// 👈 نراقب الاتنين</span></span>
<span class="line">  debouncedSave<span class="token punctuation">,</span> <span class="token comment">// 👈 لما يحصل تغيير ننفذ الحفظ</span></span>
<span class="line">  <span class="token punctuation">{</span> <span class="token literal-property property">deep</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span> <span class="token comment">// 👈 نراقب التغييرات الداخلية</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre>
