<span class="line">  <span class="token keyword">const</span> nodeId <span class="token operator">=</span> e<span class="token punctuation">.</span>node<span class="token punctuation">.</span>id<span class="token punctuation">;</span></span>
<span class="line">  <span class="token comment">// 📦 جلب العقدة من التخزين باستخدام Service</span></span>
<span class="line">  <span class="token keyword">const</span> node <span class="token operator">=</span> <span class="token function">getOne</span><span class="token punctuation">(</span>nodeId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
