<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">"📦 Node From Storage:"</span><span class="token punctuation">,</span> node<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
