<span class="line"><span class="token comment">// 📦 كل الـ Nodes الموجودة في الرسم</span></span>
<span class="line"><span class="token keyword">const</span> nodes <span class="token operator">=</span> <span class="token function">ref</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 🔗 كل الـ Edges (الروابط بين الـ Nodes)</span></span>
<span class="line"><span class="token keyword">const</span> edges <span class="token operator">=</span> <span class="token function">ref</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 📌 Selection</span></span>
<span class="line"><span class="token keyword">const</span> selectedNode <span class="token operator">=</span> <span class="token function">ref</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">const</span> selectedEdge <span class="token operator">=</span> <span class="token function">ref</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token comment">// 🚀 3️⃣ Lifecycle (تشغيل أول ما الصفحة تفتح)</span></span>
<span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token comment">// 👂 لما الكمبوننت يتركب</span></span>
<span class="line"><span class="token function">onMounted</span><span class="token punctuation">(</span>initGraph<span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// 🔄 تهيئة الجراف</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">initGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token function">loadGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token comment">// 📖 4️⃣ LOAD GRAPH (تحميل البيانات)</span></span>
<span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">loadGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 📥 نقرأ البيانات من LocalStorage</span></span>
<span class="line">  <span class="token keyword">const</span> graph <span class="token operator">=</span> <span class="token function">getGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token comment">// 🧠 لو فيه بيانات محفوظة</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>graph<span class="token punctuation">.</span>nodes<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    nodes<span class="token punctuation">.</span>value <span class="token operator">=</span> graph<span class="token punctuation">.</span>nodes</span>
<span class="line">    edges<span class="token punctuation">.</span>value <span class="token operator">=</span> graph<span class="token punctuation">.</span>edges</span>
<span class="line">  <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 🆕 لو مفيش بيانات → ننشئ جراف افتراضي</span></span>
<span class="line">    <span class="token function">createDefaultGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token comment">// 🆕 5️⃣ Create Default Graph (أول تشغيل)</span></span>
<span class="line"><span class="token comment">// ==================================================</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">createDefaultGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 🆔 إنشاء ID فريد</span></span>
<span class="line">  <span class="token keyword">const</span> startId <span class="token operator">=</span> <span class="token function">nanoid</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token keyword">const</span> endId <span class="token operator">=</span> <span class="token function">nanoid</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token comment">// 📦 إنشاء Nodes</span></span>
<span class="line">  nodes<span class="token punctuation">.</span>value <span class="token operator">=</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">id</span><span class="token operator">:</span> startId<span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">position</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">80</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">label</span><span class="token operator">:</span> <span class="token string">"Start 🚀"</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">id</span><span class="token operator">:</span> endId<span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">position</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">300</span><span class="token punctuation">,</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">200</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">label</span><span class="token operator">:</span> <span class="token string">"End 🏁"</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">]</span></span>
<span class="line">  <span class="token comment">// 🔗 ربط Start → End</span></span>
<span class="line">  edges<span class="token punctuation">.</span>value <span class="token operator">=</span> <span class="token punctuation">[</span></span>
<span class="line">    <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">id</span><span class="token operator">:</span> <span class="token function">nanoid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">source</span><span class="token operator">:</span> startId<span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">target</span><span class="token operator">:</span> endId</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">]</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token comment">/* ==================================================</span>
<span class="line">🔍 4️⃣ READ</span>
<span class="line">================================================== */</span></span>
<span class="line"></span>
<span class="line"><span class="token doc-comment comment">/**</span>
<span class="line"> * 🧩 getSingleNode(e)</span>
<span class="line"> * 🎯 وظيفتها: جلب Node واحدة من التخزين عند الضغط عليها</span>
<span class="line"> * 🧠 الفكرة:</span>
<span class="line"> * VueFlow بيبعت لنا Event فيه بيانات العقدة</span>
<span class="line"> * لكن إحنا بنرجع نجيبها من Storage علشان يكون المصدر واحد (Source of Truth)</span>
<span class="line"> */</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">getSingleNode</span><span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🆔 استخراج الـ ID من الحدث</span></span>
<span class="line">  <span class="token keyword">const</span> nodeId <span class="token operator">=</span> e<span class="token punctuation">.</span>node<span class="token punctuation">.</span>id</span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 📦 جلب العقدة من التخزين باستخدام Service</span></span>
<span class="line">  <span class="token keyword">const</span> node <span class="token operator">=</span> <span class="token function">getOne</span><span class="token punctuation">(</span>nodeId<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🎯 تخزين العقدة المختارة لعرضها في الـ Side Panel</span></span>
<span class="line">  selectedNode<span class="token punctuation">.</span>value <span class="token operator">=</span> node</span>
<span class="line"></span>
<span class="line">  <span class="token comment">// ❌ إلغاء تحديد أي Edge</span></span>
<span class="line">  selectedEdge<span class="token punctuation">.</span>value <span class="token operator">=</span> <span class="token keyword">null</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🖥️ طباعة في الكونسول للتأكد</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">"📦 Node From Storage:"</span><span class="token punctuation">,</span> node<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span class="token doc-comment comment">/**</span>
<span class="line"> * 🔗 getSingleEdge(e)</span>
<span class="line"> * 🎯 وظيفتها: جلب Edge واحدة عند الضغط عليها</span>
<span class="line"> * 🧠 نفس الفكرة بالظبط لكن مع الروابط</span>
<span class="line"> */</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">getSingleEdge</span><span class="token punctuation">(</span><span class="token parameter">e</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🆔 استخراج ID الرابط</span></span>
<span class="line">  <span class="token keyword">const</span> edgeId <span class="token operator">=</span> e<span class="token punctuation">.</span>edge<span class="token punctuation">.</span>id</span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 📦 جلب الرابط من التخزين</span></span>
<span class="line">  <span class="token keyword">const</span> edge <span class="token operator">=</span> <span class="token function">getEdge</span><span class="token punctuation">(</span>edgeId<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🎯 تخزين الرابط المختار</span></span>
<span class="line">  selectedEdge<span class="token punctuation">.</span>value <span class="token operator">=</span> edge</span>
<span class="line"></span>
<span class="line">  <span class="token comment">// ❌ إلغاء تحديد أي Node</span></span>
<span class="line">  selectedNode<span class="token punctuation">.</span>value <span class="token operator">=</span> <span class="token keyword">null</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🖥️ طباعة للتأكد</span></span>
<span class="line">  console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">"🔗 Edge From Storage:"</span><span class="token punctuation">,</span> edge<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/* ==================================================</span>
<span class="line">➕ 3️⃣ CREATE</span>
<span class="line">================================================== */</span></span>
<span class="line"></span>
<span class="line"><span class="token doc-comment comment">/**</span>
<span class="line"> * ➕ addNode()</span>
<span class="line"> * 🎯 وظيفتها: إنشاء Node جديدة داخل النظام</span>
<span class="line"> * 🧠 الفكرة:</span>
<span class="line"> * 1- ننشئ كائن يمثل العقدة</span>
<span class="line"> * 2- نحفظه في الـ Storage</span>
<span class="line"> * 3- نعمل Sync مع Vue علشان يحصل Re-render</span>
<span class="line"> */</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">addNode</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 🆔 إنشاء ID فريد لكل Node</span></span>
<span class="line">  <span class="token keyword">const</span> newNode <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">id</span><span class="token operator">:</span> <span class="token function">nanoid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token comment">// 🔑 ID فريد باستخدام مكتبة nanoid</span></span>
<span class="line">    <span class="token literal-property property">position</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">x</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span> <span class="token literal-property property">y</span><span class="token operator">:</span> <span class="token number">220</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token comment">// 📍 مكان الظهور على الشاشة</span></span>
<span class="line">    <span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">label</span><span class="token operator">:</span> <span class="token string">"Dynamic Node 🚀"</span> <span class="token punctuation">}</span> <span class="token comment">// 🏷️ البيانات الخاصة بالعقدة</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line">  <span class="token comment">// 💾 حفظ العقدة داخل Storage Service</span></span>
<span class="line">  <span class="token function">createNode</span><span class="token punctuation">(</span>newNode<span class="token punctuation">)</span></span>
<span class="line">  <span class="token comment">// 🔄 تحديث حالة Vue بالبيانات الجديدة</span></span>
<span class="line">  <span class="token function">syncGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token doc-comment comment">/**</span>
<span class="line"> * 🔄 syncGraph()</span>
<span class="line"> * 🎯 وظيفتها: مزامنة البيانات بين Storage و Vue State</span>
<span class="line"> * 🧠 ليه بنعملها؟</span>
<span class="line"> * لأننا بنخلي المصدر الأساسي للبيانات هو الـ Storage</span>
<span class="line"> * وبعد أي تعديل نرجع نقرأ منه ونعكسه على Vue</span>
<span class="line"> */</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">syncGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 📦 جلب كل البيانات من التخزين</span></span>
<span class="line">  <span class="token keyword">const</span> graph <span class="token operator">=</span> <span class="token function">getGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token comment">// 🧩 تحديث العقد</span></span>
<span class="line">  nodes<span class="token punctuation">.</span>value <span class="token operator">=</span> graph<span class="token punctuation">.</span>nodes</span>
<span class="line">  <span class="token comment">// 🔗 تحديث الروابط</span></span>
<span class="line">  edges<span class="token punctuation">.</span>value <span class="token operator">=</span> graph<span class="token punctuation">.</span>edges</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token doc-comment comment">/**</span>
<span class="line"> * 🔗 addEdge()</span>
<span class="line"> * 🎯 وظيفتها: إنشاء رابط بين عقدتين</span>
<span class="line"> * 🧠 params بتيجي من VueFlow event (@connect)</span>
<span class="line"> */</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">addEdge</span><span class="token punctuation">(</span><span class="token parameter">params</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  edges<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token operator">...</span>params<span class="token punctuation">,</span>       <span class="token comment">// 📥 بيانات المصدر والهدف</span></span>
<span class="line">    <span class="token literal-property property">id</span><span class="token operator">:</span> <span class="token function">nanoid</span><span class="token punctuation">(</span><span class="token punctuation">)</span>     <span class="token comment">// 🆔 إنشاء ID فريد للرابط</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/* ==================================================</span>
<span class="line">✏️ 5️⃣ UPDATE</span>
<span class="line">================================================== */</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/*</span>
<span class="line">🎯 updateFirstNode()</span>
<span class="line">📌 الهدف: تحديث أول Node موجود في الجراف</span>
<span class="line">*/</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">updateFirstNode</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>nodes<span class="token punctuation">.</span>value<span class="token punctuation">.</span>length<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token comment">// 🚫 لو مفيش Nodes اخرج</span></span>
<span class="line"></span>
<span class="line">  <span class="token function">updateNode</span><span class="token punctuation">(</span>nodes<span class="token punctuation">.</span>value<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span>id<span class="token punctuation">,</span> <span class="token punctuation">{</span>   <span class="token comment">// 🆔 نجيب أول Node</span></span>
<span class="line">    <span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token literal-property property">label</span><span class="token operator">:</span> <span class="token string">"Updated ✨"</span> <span class="token punctuation">}</span>   <span class="token comment">// ✨ نعدل البيانات</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">  <span class="token function">syncGraph</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token comment">// 🔄 نعمل مزامنة مع Vue State</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span class="token comment">/*</span>
<span class="line">🎯 updateNodeById(id)</span>
<span class="line">📌 الهدف: تحديث Node معين باستخدام الـ id</span>
<span class="line">🆔 id → هو المعرف الفريد للـ Node</span>
<span class="line">*/</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">updateNodeById</span><span class="token punctuation">(</span><span class="token parameter">id</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line"></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>id<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token comment">// 🚫 تأكد إن في id</span></span>
<span class="line"></span>
<span class="line">  <span class="token function">updateNode</span><span class="token punctuation">(</span>id<span class="token punctuation">,</span> <span class="token punctuation">{</span>                  <span class="token comment">// 🆔 نستخدم الـ id مباشرة</span></span>
<span class="line">    <span class="token literal-property property">data</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">label</span><span class="token operator">:</span> selectedNode<span class="token punctuation">.</span>value<span class="token punctuation">.</span>data<span class="token punctuation">.</span>label <span class="token comment">// ✍️ ناخد القيمة من input</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
