<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre v-pre><code><span class="line"><span class="token comment">// 📌 Layout Flag</span></span>
<span class="line"><span class="token keyword">const</span> isLayouting <span class="token operator">=</span> <span class="token function">ref</span><span class="token punctuation">(</span><span class="token boolean">false</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre>
<div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre v-pre><code><span class="line"><span class="token comment">/* ===================================================</span>
<span class="line">📐 7️⃣ AUTO LAYOUT (Dagre)</span>
<span class="line">=================================================== */</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">/*</span>
<span class="line">🎯 autoLayout(dir)</span>
<span class="line">📐 الهدف: ترتيب الـ Nodes تلقائيًا باستخدام Dagre</span>
<span class="line">🧭 dir:</span>
<span class="line">   'TB' = Top ➝ Bottom ⬇️</span>
<span class="line">   'LR' = Left ➝ Right ➡️</span>
<span class="line">*/</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">autoLayout</span><span class="token punctuation">(</span>dir <span class="token operator">=</span> <span class="token string">"TB"</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token comment">// 🚦 تفعيل حالة الـ Layout (لإضافة Animation مثلاً)</span></span>
<span class="line">  isLayouting<span class="token punctuation">.</span>value <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🧠 إنشاء جراف جديد في Dagre</span></span>
<span class="line">  <span class="token keyword">const</span> g <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">dagre<span class="token punctuation">.</span>graphlib<span class="token punctuation">.</span>Graph</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// ⚙️ إعدادات الجراف</span></span>
<span class="line">  g<span class="token punctuation">.</span><span class="token function">setGraph</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">rankdir</span><span class="token operator">:</span> dir<span class="token punctuation">,</span> <span class="token comment">// 🧭 اتجاه الترتيب</span></span>
<span class="line">    <span class="token literal-property property">nodesep</span><span class="token operator">:</span> <span class="token number">50</span><span class="token punctuation">,</span> <span class="token comment">// ↔️ مسافة بين الـ Nodes أفقيًا</span></span>
<span class="line">    <span class="token literal-property property">ranksep</span><span class="token operator">:</span> <span class="token number">80</span><span class="token punctuation">,</span> <span class="token comment">// ↕️ مسافة بين الصفوف</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🔗 إعداد افتراضي للـ Edges</span></span>
<span class="line">  g<span class="token punctuation">.</span><span class="token function">setDefaultEdgeLabel</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🧩 إضافة الـ Nodes إلى Dagre مع أبعاد ثابتة</span></span>
<span class="line">  nodes<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">node</span><span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token punctuation">{</span></span>
<span class="line">    g<span class="token punctuation">.</span><span class="token function">setNode</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>id<span class="token punctuation">,</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">width</span><span class="token operator">:</span> <span class="token number">180</span><span class="token punctuation">,</span> <span class="token comment">// 📏 عرض العقدة</span></span>
<span class="line">      <span class="token literal-property property">height</span><span class="token operator">:</span> <span class="token number">60</span><span class="token punctuation">,</span> <span class="token comment">// 📐 ارتفاع العقدة</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🔗 إضافة الـ Edges إلى Dagre</span></span>
<span class="line">  edges<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">forEach</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">edge</span><span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token punctuation">{</span></span>
<span class="line">    g<span class="token punctuation">.</span><span class="token function">setEdge</span><span class="token punctuation">(</span>edge<span class="token punctuation">.</span>source<span class="token punctuation">,</span> edge<span class="token punctuation">.</span>target<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🚀 تشغيل خوارزمية الترتيب</span></span>
<span class="line">  dagre<span class="token punctuation">.</span><span class="token function">layout</span><span class="token punctuation">(</span>g<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// 🔄 تحديث مواقع الـ Nodes في VueFlow</span></span>
<span class="line">  nodes<span class="token punctuation">.</span>value <span class="token operator">=</span> nodes<span class="token punctuation">.</span>value<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">node</span><span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> pos <span class="token operator">=</span> g<span class="token punctuation">.</span><span class="token function">node</span><span class="token punctuation">(</span>node<span class="token punctuation">.</span>id<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 📍 الموقع الجديد من Dagre</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">return</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token operator">...</span>node<span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">position</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token literal-property property">x</span><span class="token operator">:</span> pos<span class="token punctuation">.</span>x <span class="token operator">-</span> <span class="token number">90</span><span class="token punctuation">,</span> <span class="token comment">// 🧮 تصحيح المنتصف (width / 2)</span></span>
<span class="line">        <span class="token literal-property property">y</span><span class="token operator">:</span> pos<span class="token punctuation">.</span>y <span class="token operator">-</span> <span class="token number">30</span><span class="token punctuation">,</span> <span class="token comment">// 🧮 تصحيح المنتصف (height / 2)</span></span>
<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">  <span class="token comment">// ⏳ إنهاء حالة الـ Layout بعد الأنيميشن</span></span>
<span class="line">  <span class="token function">setTimeout</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=></span> <span class="token punctuation">{</span></span>
<span class="line">    isLayouting<span class="token punctuation">.</span>value <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token number">400</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre>
