<span class="line">    <span class="token operator">...</span>n<span class="token punctuation">,</span></span>
<span class="line">    <span class="token keyword">class</span><span class="token operator">:</span> isolatedIds<span class="token punctuation">.</span><span class="token function">includes</span><span class="token punctuation">(</span>n<span class="token punctuation">.</span>id<span class="token punctuation">)</span> <span class="token operator">?</span> <span class="token string">"isolated-node"</span> <span class="token operator">:</span> <span class="token string">""</span><span class="token punctuation">,</span></span>
